#include <stdio.h>

void incrementer(int *n) {
    *n = *n + 1; // modifie la variable originale
}

int main() {
    int age = 25;
    int *p = &age; // p pointe sur age

    printf("Valeur : %d\n", age);    // 25
    printf("Adresse : %p\n", p);     // 0x7fff...
    printf("Via ptr : %d\n", *p);   // 25

    *p = 30; // modifie age via le pointeur
    printf("Après : %d\n", age);    // 30

    incrementer(&age);
    printf("Après incr : %d\n", age); // 31
    return 0;
}
